  ('children', 'children', '04', 'Детские стрижки', 'Детские стрижки', 'Спокойный и аккуратный подход к маленьким гостям салона.', 'from', 200, NULL, NULL, 'от 200 ₽', NULL, '["dzhulia","snezhana","yulia"]', 1, 3),
  ('texture', 'texture', '05', 'Биозавивка и прикорневой объём', 'Завивка и объём', 'Мягкая долговременная текстура и объём с учётом длины волос.', 'from', 3500, NULL, NULL, 'от 3 500 ₽', 'Цены для коротких / средних / длинных волос.', '["snezhana"]', 1, 4),
