INSERT INTO `offers` (`id`, `linked_service_id`, `type`, `slug`, `title`, `short_title`, `eyebrow`, `description`, `legal_note`, `benefit_type`, `benefit_value`, `nominal_value`, `currency`, `free_visit_number`, `front_storage_key`, `front_url`, `back_storage_key`, `back_url`, `valid_from`, `valid_until`, `is_transferable`, `can_combine_with_other_offers`, `status`, `sort_order`)
VALUES
  ('offer:loyalty-sixth-haircut', NULL, 'loyalty', 'sixth-haircut-free', 'Каждая шестая стрижка — в подарок', 'Шестая стрижка бесплатно', 'Для новых клиентов', 'Получите физическую карточку после первого визита. В акции участвуют мужская и женская модельные стрижки, стрижка кончиков и чёлки.', 'Учёт посещений ведёт салон на физической карточке. Акцию можно совмещать с сертификатом: оставшиеся скидки сертификата сохраняются для других услуг.', 'free_nth_visit', NULL, NULL, 'RUB', 6, NULL, '/images/loyalty-card-front.webp', NULL, '/images/loyalty-card-back.webp', NULL, NULL, 0, 1, 'active', 0),
  ('offer:discount-certificate', 'service:certificate:discount-card', 'certificate', 'discount-certificate', 'Скидочный сертификат «Ассоль»', 'Сертификат до 1 000 ₽ выгоды', 'Получите бесплатно или купите за 1 000 ₽', 'Сертификат выдаётся бесплатно при покупке одной услуги дороже 3 000 ₽. Его также можно приобрести отдельно, подарить или передать близкому человеку.', 'Каждая скидка используется один раз. Маникюр и педикюр делят одну общую скидку 200 ₽. Сертификат можно совмещать с акцией на шестую стрижку.', 'nominal', NULL, 1000, 'RUB', NULL, NULL, '/images/certificate-front.webp', NULL, '/images/certificate-back.webp', NULL, NULL, 1, 1, 'active', 1)
